-- Generated by alchemists-tools probe (@COMMAND@).
-- Logs calls to game functions and changes nothing. Output: ue4ss/UE4SS.log, lines starting
-- with [@NAME@]. Ctrl + Numpad 3 logs how often each function has been called, and Ctrl + Numpad 2 what the
-- watched new objects hold.

local Library = require("AlchemistsLibrary")
local log = Library.logger("@NAME@")
local LIMIT = @LIMIT@  -- calls logged in full, per function
local REPEATS = @REPEATS@  -- calls logged in full that look the same (numbers aside), per function

-- {path, params = {{name, type, layout}}, returns = {type, layout}}; params is nil for a Blueprint function
-- (arguments logged unnamed), returns is nil for a function returning nothing
local HOOKS = @HOOKS@

-- Classes whose new objects are logged
local NEW_OBJECTS = @NEW_OBJECTS@

local calls = {}

local function context_text(context)
    local ok, object = pcall(function() return context:get() end)
    if not ok then return "?" end
    local text = Library.describe(object)
    local has_owner, owner = pcall(function() return object:GetOwner() end)
    if has_owner and owner and owner:IsValid() then
        local row = Library.building_row(owner)
        text = text .. " (owner " .. owner:GetFName():ToString() .. (row and (", row " .. row) or "") .. ")"
        local authority = Library.has_authority(owner)
        if authority ~= nil then text = text .. (authority and ", has authority" or ", no authority") end
    end
    return text
end

local function arguments_text(hook, arguments)
    local parts = {}
    local count = hook.params and #hook.params or #arguments
    for i = 1, count do
        local ok, value = pcall(function() return arguments[i]:get() end)
        local param = hook.params and hook.params[i]
        local label = param and param.name or ("argument " .. i)
        parts[#parts + 1] = label .. " = " .. (ok and Library.describe(value, param and param.layout) or "?")
    end
    return table.concat(parts, "; ")
end

-- What a call returned, read after it ran. UE4SS may pass the return value to the post-hook after the
-- parameters; if it doesn't, the log says how many values it did pass. Out parameters (references) are
-- read again too, since the call may have filled them.
local function results_text(hook, arguments, returned)
    local parts = {}
    -- For a function with parameters, the value after them is the last parameter (or something read as
    -- its type), not the return value: GetBuildingStateCost's "return value" was its State argument
    -- (BlueprintCostReader, 2026-10-19). Only a function without parameters gets its return value.
    if hook.returns and hook.params and #hook.params > 0 then
        hook = {params = hook.params}
    end
    if hook.returns then
        local value = returned
        if value == nil and hook.params and #arguments > #hook.params then
            local ok, unwrapped = pcall(function() return arguments[#hook.params + 1]:get() end)
            value = ok and unwrapped or nil
        end
        if value ~= nil then
            local ok, unwrapped = pcall(function() return value:get() end)
            if ok and unwrapped ~= nil then value = unwrapped end
            parts[#parts + 1] = "returned " .. Library.describe(value, hook.returns.layout)
        else
            parts[#parts + 1] = string.format("returned ? (%s; the post-hook got %d value(s))",
                hook.returns.type, #arguments)
        end
    end
    for i, param in ipairs(hook.params or {}) do
        if param.type:find("&") and not param.type:find("const") then
            local ok, value = pcall(function() return arguments[i]:get() end)
            parts[#parts + 1] = param.name .. " = " .. (ok and Library.describe(value, param.layout) or "?")
        end
    end
    return table.concat(parts, "; ")
end

-- Calls whose arguments look alike once numbers are set aside (a tick's frame number, a position) are
-- logged REPEATS times, then only counted. Array lengths ("[3]") stay, as letters: an empty tick and one
-- with commands in it differ by them
local function shape_of(text)
    local shape = text:gsub("%[(%d+)%]", function(length)
        return "[" .. (length:gsub("%d", function(digit) return string.char(97 + tonumber(digit)) end)) .. "]"
    end)
    return (shape:gsub("%-?%d+%.?%d*", "#"))
end

-- Per function: how many calls of each shape were logged, and the number logged in all
local shapes = {}
-- Whether to log a call of this shape, counting it if so
local function take(path, shape)
    local seen = shapes[path]
    seen[shape] = (seen[shape] or 0) + 1
    local logged_so_far = seen[""] or 0
    if seen[shape] > REPEATS or logged_so_far >= LIMIT then return nil end
    seen[""] = logged_so_far + 1
    return (seen[""] == LIMIT and " (the last logged in full)" or "")
        .. (seen[shape] == REPEATS and " (more like it are only counted)" or "")
end

-- Per function, for each call still running: its arguments' text, and whether it was logged
local running = {}

local hooked = {}

local function try_hook(hook)
    if hooked[hook.path] then return end
    running[hook.path] = {}
    shapes[hook.path] = shapes[hook.path] or {}
    local ok, error_message = pcall(RegisterHook, hook.path, function(context, ...)
        local arguments = {...}
        local call = {text = "?", logged = false}
        Library.safely(log, function()
            calls[hook.path] = (calls[hook.path] or 0) + 1
            call.number = calls[hook.path]
            call.text = arguments_text(hook, arguments)
            local note = take(hook.path, shape_of(call.text))
            if not note then return end
            call.logged = true
            log.log(string.format("%s call %d%s, on %s: %s", hook.path, call.number, note, context_text(context),
                call.text))
        end)
        table.insert(running[hook.path], call)
    end, function(context, ...)
        local arguments = {...}
        local call = table.remove(running[hook.path]) or {text = "?", logged = false}
        -- UE4SS may hand the post-hook the return value after the parameters; select keeps a trailing nil
        local returned = nil
        if hook.params and select("#", ...) > #hook.params then returned = select(#hook.params + 1, ...) end
        Library.safely(log, function()
            local results = results_text(hook, arguments, returned)
            if results == "" then return end
            if call.logged then
                log.log(string.format("%s call %d: %s", hook.path, call.number or calls[hook.path], results))
                return
            end
            -- A call skipped as a repeat is still logged when what it returned is new (a getter with no
            -- arguments, say)
            local note = take(hook.path, "returned " .. shape_of(call.text .. " -> " .. results))
            if note then
                log.log(string.format("%s call %d%s (new result), on %s: %s -> %s", hook.path,
                    call.number or calls[hook.path], note, context_text(context), call.text, results))
            end
        end)
    end)
    if ok then
        hooked[hook.path] = true
        log.log("hooked " .. hook.path)
    else
        log.once("can't hook " .. hook.path .. " yet: " .. tostring(error_message))
    end
end

for _, hook in ipairs(HOOKS) do try_hook(hook) end
-- A Blueprint's functions exist only once it's loaded: try again until each is hooked
LoopInGameThreadWithDelay(2000, function()
    for _, hook in ipairs(HOOKS) do try_hook(hook) end
end)

-- New objects, newest last (at most 200), for Ctrl + Numpad 2
local new_objects = {}

for _, class in ipairs(NEW_OBJECTS) do
    NotifyOnNewObject(class, function(object)
        Library.safely(log, function()
            log.log("new " .. class .. ": " .. Library.describe(object))
            new_objects[#new_objects + 1] = object
            if #new_objects > 200 then table.remove(new_objects, 1) end
            -- Again a moment later, once it has been set up. Only light checks here: this runs while a world
            -- loads too, and reading containers then crashed the game (AlchemistsLibrary 0.2.0)
            ExecuteWithDelay(500, function()
                Library.on_game_thread(log, function()
                    if object:IsValid() then
                        log.log("   0.5 s later: " .. Library.describe(object) .. ", row "
                            .. tostring(Library.building_row(object)))
                    end
                end)
            end)
        end)
    end)
end

-- What the new objects hold: press once the world has loaded
Library.keybind(Key.NUM_TWO, {ModifierKey.CONTROL}, log, function()
    local shown = 0
    for i, object in ipairs(new_objects) do
        if object:IsValid() then
            local held = {}
            -- the newest object's lookup is reported step by step, to see why something holds nothing
            local report = i == #new_objects and function(line) log.log("   " .. line) end or nil
            for _, item in ipairs(Library.contents(object, report)) do
                held[#held + 1] = item.count .. " " .. item.name
            end
            log.log(Library.describe(object) .. " holds: " .. (#held > 0 and table.concat(held, ", ") or "nothing"))
            shown = shown + 1
        end
    end
    log.log(string.format("%d new object(s) still exist", shown))
end)

Library.keybind(Key.NUM_THREE, {ModifierKey.CONTROL}, log, function()
    for _, path in ipairs(Library.sorted_keys(calls)) do
        log.log(string.format("%s: %d call(s)", path, calls[path]))
    end
    if next(calls) == nil then log.log("no calls yet") end
end)

log.log(string.format("loaded: %d function(s), %d class(es) watched", #HOOKS, #NEW_OBJECTS))
